 1	import { readFileSync, writeFileSync } from 'node:fs';
 2	import { deflateSync } from 'node:zlib';
 3	
 4	const out = process.argv[2];
 5	if (!out) throw new Error('usage: node shot.mjs <file.png>');
 6	const html = readFileSync(new URL('./index.html', import.meta.url), 'utf8');
 7	const button = /<button[^>]*style="([^"]*)"/.exec(html)?.[1] ?? '';
 8	const hex = /background:\s*#([0-9a-f]{6})/i.exec(button)?.[1] ?? '888888';
 9	const left = Number(/margin-left:\s*(\d+)px/.exec(button)?.[1] ?? 0);
10	const color = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
11	const W = 480, H = 320;
12	const rects = [[0, 0, 480, 36, [38, 52, 84]], [110, 70, 370, 280, [255, 255, 255]], [130, 124, 350, 148, [214, 216, 222]], [130, 162, 350, 186, [214, 216, 222]], [130 + left, 214, 350 + left, 246, color]];
13	const raw = Buffer.alloc((W * 3 + 1) * H);
14	for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
15	  const rgb = rects.findLast(([a, b, c, d]) => x >= a && x < c && y >= b && y < d)?.[4] ?? [248, 248, 246];
16	  raw.set(rgb, y * (W * 3 + 1) + 1 + x * 3);
17	}
18	const table = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
19	const crc = (bytes) => { let c = 0xffffffff; for (const b of bytes) c = table[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
20	const chunk = (type, data) => { const head = Buffer.alloc(8); head.writeUInt32BE(data.length); head.write(type, 4); const sum = Buffer.alloc(4); sum.writeUInt32BE(crc(Buffer.concat([head.subarray(4), data]))); return Buffer.concat([head, data, sum]); };
21	const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(W); ihdr.writeUInt32BE(H, 4); ihdr.set([8, 2, 0, 0, 0], 8);
22	writeFileSync(out, Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', ihdr), chunk('IDAT', deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]));
23	console.log(`saved ${out}`);

